"""Documentacao da 227a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 227
R = [('casar_chave_de_clube', 'match_club_key_id', '0x6146b0', 'index.cpp', 'cdecl', 'casa o nome do clube da base com as 313 chaves fixas de clube (372 nomes em 4 cadeias, _stricmp): o primeiro acerto de cada cadeia grava a linha na global da chave', 'matches the database club name with the 313 fixed club keys (372 names in 4 chains, _stricmp): the first hit of each chain stores the row in the key global'), ('remapear_chave_de_clube', 'remap_club_key_id', '0x60ba80', 'index.cpp', 'cdecl', 'depois do corte da tabela de clubes, a primeira chave de clube que guarda o id antigo passa a guardar o novo (devolve 1; nenhuma: 0)', 'after the club table trim, the first club key holding the old id gets the new one (returns 1; none: 0)'), ('casar_chave_de_nacao', 'match_nation_key_id', '0x60d810', 'index.cpp', 'cdecl', 'casa o nome da nação da base com as 209 chaves fixas de nação (217 nomes em 2 cadeias, _stricmp)', 'matches the database nation name with the 209 fixed nation keys (217 names in 2 chains, _stricmp)'), ('casar_chave_de_competicao_de_clube', 'match_club_comp_key_id', '0x60efd0', 'index.cpp', 'cdecl', 'casa o nome longo da competição de clube com as 301 chaves fixas (351 nomes em 3 cadeias, _stricmp; as duas divisões croatas gravam também 0x9cf8a4)', 'matches the club competition long name with the 301 fixed keys (351 names in 3 chains, _stricmp; the two Croatian divisions also store 0x9cf8a4)'), ('casar_chave_de_competicao_de_pessoa', 'match_staff_comp_key_id', '0x6115e0', 'index.cpp', 'cdecl', 'casa o nome da competição ou prêmio de pessoa com as 417 chaves fixas (442 nomes em 5 cadeias, _stricmp)', 'matches the staff competition or award name with the 417 fixed keys (442 names in 5 chains, _stricmp)')]
ESCAPADAS = {  # nome: (explicação pt, explicação en)
    'ix2_comp_pessoa': ('as chaves de competição de pessoa (0x9cfa20..0x9d00a0) são globais do exe, não vão para o .qst, e o início rápido não as lê antes de gravar; a prova do save (que avalia as mutações das levas do save) não as vê', 'the person competition keys (0x9cfa20..0x9d00a0) are exe globals, not written into the .qst, and the quick start does not read them before saving; the save proof (which evaluates the save batch mutations) does not see them'),
    'ix2_devolucao': ('quem chama (set_key_ids 0x601a40) ignora a devolução das rotinas de casar a chave (o resultado do último _stricmp)', 'the caller (set_key_ids 0x601a40) ignores the return value of the key matching routines (the result of the last _stricmp)'),
}
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 621, 621 + len(R), 'as chaves fixas de clube e de nação pelo nome e a troca da chave de clube depois do corte da base; as chaves fixas das competições de clube e das competições e prêmios de pessoa pelo nome', 'the fixed club and nation keys by name and the club key remap after the database trim; the fixed club competition and staff competition/award keys by name',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'as chaves fixas de clube e de nação pelo nome e a troca da chave de clube depois do corte da base; as chaves fixas das competições de clube e das competições e prêmios de pessoa pelo nome', 'the fixed club and nation keys by name and the club key remap after the database trim; the fixed club competition and staff competition/award keys by name', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('[0x9d00a4..0x9d0524] e [0xb63c9c..0xb63d00]: as 313 chaves de clube (nomes reais na tabela CHAVES_DE_CLUBE do codigo.rs: MLS All Stars East/West, River Plate, Vélez Sarsfield, Everton, Tottenham Hotspur, Chelsea, Valencia C.F., FC St. Pauli, Arminia Bielefeld...; grafias diferentes dão na mesma chave); id (linha da tabela de clubes); grava (casar_chave_de_clube), lê e grava (remapear_chave_de_clube)', '[0x9d00a4..0x9d0524] and [0xb63c9c..0xb63d00]: the 313 club keys (real names in the CHAVES_DE_CLUBE table of codigo.rs: MLS All Stars East/West, River Plate, Vélez Sarsfield, Everton, Tottenham Hotspur, Chelsea, Valencia C.F., FC St. Pauli, Arminia Bielefeld...; different spellings map to the same key); id (club table row); writes (casar_chave_de_clube), reads and writes (remapear_chave_de_clube)'), ('[0x9cf200..0x9cf544]: as 209 chaves de nação (0x9cf200 Afghanistan, 0x9cf204 Albania...; nomes em CHAVES_DE_NACAO, 217 com as grafias); id (linha da tabela de nações); grava (casar_chave_de_nacao)', '[0x9cf200..0x9cf544]: the 209 nation keys (0x9cf200 Afghanistan, 0x9cf204 Albania...; names in CHAVES_DE_NACAO, 217 with the spellings); id (nation table row); writes (casar_chave_de_nacao)'), ('clube/nação +nome: o nome que a base dá (argumento das rotinas de casar); texto; lê (por _stricmp 0x951c50, sem distinguir maiúsculas; com o locale em [0xde3040+8])', 'club/nation +name: the name the database gives (argument of the match routines); text; reads (through _stricmp 0x951c50, case-insensitive; with the locale at [0xde3040+8])'), ('[0x9cf548..0x9cfa04]: as 301 chaves de competição de clube (nomes reais em CHAVES_DE_COMPETICAO_DE_CLUBE do codigo.rs: French Lower Division, German First Division, World Club Cup, UEFA Champions League, turkish premier division...; croatian first division e croatian a1 division gravam 0x9cf87c e 0x9cf8a4); id (linha da tabela de competições de clube); grava (casar_chave_de_competicao_de_clube)', '[0x9cf548..0x9cfa04]: the 301 club competition keys (real names in CHAVES_DE_COMPETICAO_DE_CLUBE of codigo.rs: French Lower Division, German First Division, World Club Cup, UEFA Champions League, turkish premier division...; croatian first division and croatian a1 division store 0x9cf87c and 0x9cf8a4); id (club competition table row); writes (casar_chave_de_competicao_de_clube)'), ('[0x9cfa20..0x9d00a0]: as 417 chaves de competição e prêmio de pessoa (nomes em CHAVES_DE_COMPETICAO_DE_PESSOA: FIFA World Player of the Year, European Footballer of the Year, Italian Serie A Team of the Year, Brazilian 1st Division Top Goalscorer...); id (linha da tabela de competições de pessoa); grava (casar_chave_de_competicao_de_pessoa)', '[0x9cfa20..0x9d00a0]: the 417 staff competition and award keys (names in CHAVES_DE_COMPETICAO_DE_PESSOA: FIFA World Player of the Year, European Footballer of the Year, Italian Serie A Team of the Year, Brazilian 1st Division Top Goalscorer...); id (staff competition table row); writes (casar_chave_de_competicao_de_pessoa)'), ('competição +nome longo / competição de pessoa +nome: o nome que a base dá (argumento); texto; lê (por _stricmp 0x951c50, sem distinguir maiúsculas)', 'competition +long name / staff competition +name: the name the database gives (argument); text; reads (through _stricmp 0x951c50, case-insensitive)')], interessa=['CMRTE', 'SGE'])
